// Shared esbuild options for bundling packages/shared into the Supabase edge functions.
import { resolve } from 'node:path';

export function functionsBundleOptions(root) {
  return {
    entryPoints: [resolve(root, 'packages/shared/src/index.ts')],
    outfile: resolve(root, 'supabase/functions/_shared/kiwar-shared.js'),
    bundle: true,
    format: 'esm',
    platform: 'neutral',
    target: 'es2022',
    minify: false,
    legalComments: 'inline',
    banner: {
      js: '// GENERATED by scripts/build-functions.mjs from packages/shared — do not edit.\n// deno-lint-ignore-file',
    },
  };
}
